package com.example.starter.incident;

import java.time.Instant;

/**
 * 事件资源实体，对应 incident_resources 表。
 * resourceKey 全局唯一；holderIncidentId 为登记持有事件，借出期间不变更，
 * 借出期间的责任方由进行中的互助交接表达。
 * 时间均为 UTC。
 */
public record IncidentResource(
        long id,
        String resourceKey,
        long holderIncidentId,
        String acquiredBy,
        Instant acquiredAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 事件代理人实体，对应 incident_delegates 表。
 * (incidentId, delegate) 唯一；代理人具互助交接接收权限。
 * 时间均为 UTC。
 */
public record IncidentDelegate(
        long id,
        long incidentId,
        String delegate,
        String registeredBy,
        Instant createdAt) {
}

package com.example.starter.incident;

/**
 * 互助交接状态机：ACTIVE → SETTLED。
 * 目标关闭或租约到期触发结束（记录 endReason/endTriggeredAt），
 * 全部资源项归还来源后进入 SETTLED 终态。
 */
public enum HandoffStatus {

    /** 进行中（含已触发结束但仍有已开始任务占用资源、等待结算）。 */
    ACTIVE,

    /** 已结算：全部资源项已归还来源，终态。 */
    SETTLED;
}

package com.example.starter.incident;

/**
 * 交接结束触发原因（同时作为结算原因写入不可变交接结算）。
 */
public enum SettlementReason {

    /** 目标事件关闭触发归还。 */
    TARGET_CLOSED,

    /** 租约到期触发归还。 */
    LEASE_EXPIRED;
}

