package com.example.starter.incident;

import java.time.Instant;

/**
 * 互助交接资源项实体，对应 resource_handoff_items 表。
 * (handoffId, resourceKey) 唯一；settledAt 为该资源归还来源的结算 UTC 时间，未结算为空。
 */
public record HandoffItem(
        long id,
        long handoffId,
        String resourceKey,
        Instant settledAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 交接资源-目标任务引用实体，对应 handoff_task_refs 表。
 * (itemId, taskId) 唯一；任务终态或交接结算时解除（删除行）。
 * 时间均为 UTC。
 */
public record HandoffTaskRef(
        long id,
        long handoffId,
        long itemId,
        long taskId,
        Instant createdAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 交接结算实体，对应 handoff_settlements 表（不可变，仅插入）。
 * 每个资源项至多一条结算（uk_settlement_item 唯一约束兜底）；
 * returnedToIncidentId 为归还去向（来源事件）。时间均为 UTC。
 */
public record HandoffSettlement(
        long id,
        long handoffId,
        long itemId,
        String resourceKey,
        SettlementReason reason,
        long returnedToIncidentId,
        Instant settledAt) {
}

